import re
from pathlib import Path


def parse_env_file(env_file: str | Path) -> dict[str, str]:
    """Parse a simple .env file into a dict.

    Supports:
      - blank lines and full-line comments
      - optional `export` prefix
      - single or double quoted values
      - values containing `=` characters
    """
    path = Path(env_file)
    if not path.exists():
        return {}

    try:
        text = path.read_text(encoding="utf-8")
    except OSError:
        return {}

    values = {}

    for raw_line in text.splitlines():
        line = raw_line.strip()

        if not line or line.startswith("#"):
            continue

        if line.startswith("export "):
            line = line.split(" ", 1)[1].lstrip()

        if "=" not in line:
            continue

        key, value = line.split("=", 1)
        key = key.strip()
        value = value.strip()

        if value and value[0] in ("'", '"'):
            quote = value[0]
            escaped = False
            end = -1

            for i, ch in enumerate(value[1:], start=1):
                if escaped:
                    escaped = False
                elif ch == "\\" and quote == '"':
                    escaped = True
                elif ch == quote:
                    end = i
                    break

            if end != -1:
                value = value[1:end]
        else:
            # Strip unquoted inline comments, e.g.  KEY=value # comment
            value = re.split(r"\s+#", value, maxsplit=1)[0].strip()

        values[key] = value

    return values


def get_env_value(
    env_file: str | Path,
    key: str,
    default: str | None = None,
) -> str | None:
    """Return one value from a .env file, or `default` if missing."""
    return parse_env_file(env_file).get(key, default)

def get_env_value(key, default=None, env_file=".env"):
    values = {}

    try:
        with open(env_file, "r", encoding="utf-8") as f:
            for line in f:
                line = line.strip()

                if not line or line.startswith("#") or "=" not in line:
                    continue

                if line.startswith("export "):
                    line = line[7:]

                k, v = line.split("=", 1)
                k = k.strip()
                v = v.strip()

                # Remove surrounding quotes if present
                if len(v) >= 2 and v[0] == v[-1] and v[0] in ("'", '"'):
                    v = v[1:-1]

                values[k] = v

    except FileNotFoundError:
        return default

    return values.get(key, default)

