from typing import Iterable, Mapping, Any


def format_table(records: Iterable[Mapping[str, Any]]) -> str:
    """Format a list of dict records as an aligned text table."""
    records = list(records)

    if not records:
        return "(no records)"

    # Collect headers in insertion order, adding any extra keys found later.
    headers = list(records[0].keys())
    for record in records[1:]:
        for key in record.keys():
            if key not in headers:
                headers.append(key)

    # Build rows and calculate column widths.
    rows = []
    widths = {header: len(header) for header in headers}

    for record in records:
        row = []
        for header in headers:
            value = record.get(header, "")
            if value is None:
                value = ""
            value = str(value)
            row.append(value)
            widths[header] = max(widths[header], len(value))
        rows.append(row)

    def format_row(values):
        return "| " + " | ".join(
            f"{value:<{widths[header]}}"
            for header, value in zip(headers, values)
        ) + " |"

    border = "+" + "+".join("-" * (widths[header] + 2) for header in headers) + "+"

    lines = [
        border,
        format_row(headers),
        border,
    ]
    lines.extend(format_row(row) for row in rows)
    lines.append(border)

    return "\n".join(lines)


def print_table(records: Iterable[Mapping[str, Any]]) -> None:
    """Print a list of record dicts as an aligned table."""
    print(format_table(records))

