"""Simple in-memory TTL cache decorator."""

from __future__ import annotations

import inspect
import time
from functools import wraps
from threading import Lock
from typing import Any, Callable, TypeVar

F = TypeVar("F", bound=Callable[..., Any])


def ttl_cache(ttl: float, maxsize: int = 128) -> Callable[[F], F]:
    """
    Cache the return value of a function for `ttl` seconds.

    Works for both sync and async functions.

    Args:
        ttl: Time to live in seconds.
        maxsize: Maximum number of cached entries before eviction.

    Example:
        @ttl_cache(ttl=60)
        def expensive_computation(data: dict) -> dict:
            ...

        @ttl_cache(ttl=30)
        async def expensive_remote_call(job_id: int) -> dict:
            ...
    """
    if ttl <= 0:
        raise ValueError("ttl must be greater than 0")
    if maxsize <= 0:
        raise ValueError("maxsize must be greater than 0")

    def decorator(func: F) -> F:
        cache: dict[Any, tuple[Any, float]] = {}
        lock = Lock()

        def make_key(args: tuple[Any, ...], kwargs: dict[str, Any]) -> Any:
            # Same hashability requirement as functools.lru_cache.
            if kwargs:
                return (args, tuple(sorted(kwargs.items())))
            return args

        def evict_expired(now: float) -> None:
            expired = [
                key
                for key, (_, exp) in cache.items()
                if exp <= now
            ]
            for key in expired:
                del cache[key]

        if inspect.iscoroutinefunction(func):
            @wraps(func)
            async def async_wrapper(*args: Any, **kwargs: Any) -> Any:
                key = make_key(args, kwargs)
                now = time.monotonic()

                with lock:
                    hit = cache.get(key)
                    if hit is not None:
                        value, exp = hit
                        if exp > now:
                            return value
                        del cache[key]

                value = await func(*args, **kwargs)

                with lock:
                    cache[key] = (value, time.monotonic() + ttl)
                    if len(cache) > maxsize:
                        evict_expired(time.monotonic())
                        if len(cache) > maxsize:
                            oldest_key = next(iter(cache))
                            del cache[oldest_key]

                return value

            return async_wrapper  # type: ignore[return-value]

        @wraps(func)
        def sync_wrapper(*args: Any, **kwargs: Any) -> Any:
            key = make_key(args, kwargs)
            now = time.monotonic()

            with lock:
                hit = cache.get(key)
                if hit is not None:
                    value, exp = hit
                    if exp > now:
                        return value
                    del cache[key]

            value = func(*args, **kwargs)

            with lock:
                cache[key] = (value, time.monotonic() + ttl)
                if len(cache) > maxsize:
                    evict_expired(time.monotonic())
                    if len(cache) > maxsize:
                        oldest_key = next(iter(cache))
                        del cache[oldest_key]

            return value

        return sync_wrapper  # type: ignore[return-value]

    return decorator

