import phonenumbers
from phonenumbers import NumberParseException, PhoneNumberFormat


def validate_phone_number(phone_number: str, default_region: str = "US") -> bool:
    """Return True if the phone number is valid for the given region."""
    try:
        parsed = phonenumbers.parse(phone_number, default_region)
        return phonenumbers.is_valid_number(parsed)
    except NumberParseException:
        return False


def format_phone_number(phone_number: str, default_region: str = "US") -> str:
    """
    Validate and return the phone number in E.164 international format.

    Example:
        "+1 (202) 555-0142" -> "+12025550142"
        "020 7946 0958"  with default_region="GB" -> "+442079460958"
    """
    try:
        parsed = phonenumbers.parse(phone_number, default_region)
    except NumberParseException as exc:
        raise ValueError("Invalid phone number") from exc

    if not phonenumbers.is_valid_number(parsed):
        raise ValueError("Invalid phone number")

    return phonenumbers.format_number(parsed, PhoneNumberFormat.E164)

