T = TypeVar("T", bound=BaseModel)


class BodyValidationError(ValueError):
    """Raised when a request body is invalid or doesn't match the model."""

    def __init__(self, message: str, errors: list[dict[str, Any]] | None = None):
        super().__init__(message)
        self.errors = errors or []


def parse_and_validate(
    body: str | bytes | dict[str, Any],
    model: type[T],
) -> T:
    """
    Parse a JSON request body and validate it into a Pydantic model.

    Accepts:
      - raw JSON as ``str`` or ``bytes``
      - an already-parsed ``dict``
    """
    if isinstance(body, (str, bytes)):
        try:
            body = json.loads(body)
        except json.JSONDecodeError as exc:
            raise BodyValidationError("Request body must be valid JSON") from exc

    if not isinstance(body, dict):
        raise BodyValidationError("Request body must be a JSON object")

    try:
        return model.model_validate(body)
    except ValidationError as exc:
        raise BodyValidationError(
            "Request body failed validation",
            errors=exc.errors(),
        ) from exc


async def parse_request_body(request: Request, model: type[T]) -> T:
    """Read the request body from a FastAPI Request and validate it."""
    raw_body = await request.body()
    return parse_and_validate(raw_body, model)

