from typing import Any


def _is_numeric(value: Any) -> bool:
    """Return True for ints, floats, or strings that look numeric."""
    if isinstance(value, bool):
        return False
    if isinstance(value, (int, float)):
        return True
    if isinstance(value, str):
        try:
            float(value)
            return True
        except ValueError:
            return False
    return False


def print_table(
    records: Iterable[Mapping[str, Any]],
    columns: Sequence[str] | None = None,
) -> None:
    """Print a list of record dicts as an aligned plain-text table."""
    records = list(records)

    if not records:
        print("(no records)")
        return

    if columns is None:
        columns = []
        seen = set()
        for record in records:
            for key in record.keys():
                if key not in seen:
                    columns.append(key)
                    seen.add(key)

    headers = [str(col) for col in columns]

    rows = []
    for record in records:
        rows.append([
            "" if record.get(col) is None else str(record.get(col))
            for col in columns
        ])

    widths = [len(header) for header in headers]
    for row in rows:
        for i, cell in enumerate(row):
            widths[i] = max(widths[i], len(cell))

    # Right-align columns where all values look numeric.
    numeric_columns = set()
    for i, col in enumerate(columns):
        non_empty = [
            record.get(col)
            for record in records
            if record.get(col) is not None and str(record.get(col)).strip() != ""
        ]
        if non_empty and all(_is_numeric(value) for value in non_empty):
            numeric_columns.add(i)

    def format_row(row: Sequence[str]) -> str:
        parts = []
        for i, cell in enumerate(row):
            if i in numeric_columns:
                parts.append(cell.rjust(widths[i]))
            else:
                parts.append(cell.ljust(widths[i]))
        return "  ".join(parts)

    print(format_row(headers))
    print("  ".join("-" * width for width in widths))

    for row in rows:
        print(format_row(row))

from difflib import SequenceMatcher

def find_closest_match(query: str, names: list[str]) -> str | None:
    """
    Return the name from `names` that most closely matches `query`.

    Matching is case-insensitive and ignores leading/trailing whitespace.
    Returns None if the list is empty or the query is blank.
    """
    if not names:
        return None

    q = query.strip().lower()
    if not q:
        return None

    def similarity(name: str) -> float:
        n = name.strip().lower()
        if not n:
            return 0.0
        return SequenceMatcher(None, q, n).ratio()

    return max(names, key=similarity)

import time
import functools

def ttl_cache(ttl_seconds):
    def decorator(func):
        cache = {}

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # Build a cache key from args and kwargs
            key = (args, frozenset(kwargs.items()))

            # If key in cache and not expired, return cached value
            if key in cache:
                value, timestamp = cache[key]
                if time.time() - timestamp < ttl_seconds:
                    return value

            # Compute result, store it with current time
            result = func(*args, **kwargs)
            cache[key] = (result, time.time())
            return result

        return wrapper
    return decorator

